//////////////////////////////////////////////////////////////////////
//  [2,24] W-split cubic-contact cover workbench.
//
//  This follows the open non-d=0 route:
//
//      f = H^2 + Kappa*(x^2 + U*x + V)^3
//
//  on the A(8) chart, intersected with the W-split condition.  The
//  W-split surface is generated by beta via
//
//      beta^2*(2*d + a + beta^2)^2 - 4*(d^2+c)*beta^2 - b^2 = 0,
//
//  which is quadratic in p for fixed (r,t,beta).
//
//  Modes:
//    Mode:="stats"   : build the symbolic cover equations and report
//                      degrees/term counts.
//    Mode:="ff_disc" : finite-field W-split/contact survey, grouped by
//                      exact disc(q3)=U^2-4V fibers.
//    Mode:="tri_stats"
//                    : on disc(q3)=Delta, eliminate Kappa,H2,H1,H0
//                      triangularly from the top contact coefficients and
//                      report the residual equation sizes in
//                      (r,p,t,beta,U,H3).
//    Mode:="p_resultants"
//                    : after the triangular reduction, eliminate p against
//                      the W-split equation by resultants.  Optional exact
//                      slices: FixU, FixBeta, FixTRatio.
//    Mode:="zero_slice"
//                    : with FixU and FixBeta set, solve/analyze the exact
//                      zero-dimensional slice in variables (r,p,t,M).
//    Mode:="zero_slice_ff"
//                    : finite-field direct scan of the triangular fixed
//                      Delta equations.  If FixU/FixBeta are not set, scan
//                      all slices and report the most populated ones.
//    Mode:="slice_grid_ff"
//                    : finite-field scan of small integer (U,beta) slices,
//                      scored across primes to select exact candidates.
//    Mode:="slice_grid_rat_ff"
//                    : finite-field scan of small rational (U,beta) slices
//                      of bounded numerator/denominator height RatGridH.
//    Mode:="beta0_u0_branches"
//                    : exact branch analysis for the recurring
//                      Delta=2,U=0,beta=0 slice, where W splits into
//                      t=1 and p=r branches.
//    Mode:="beta0_u0_branch_search"
//                    : bounded rational search on those two branches,
//                      using the residual linear in M^2.
//    Mode:="fixed_slice_search"
//                    : for fixed Delta,U,beta, search rational (r,t),
//                      solve W for rational p, then solve residuals in M.
//
//  Usage:
//    magma -b Mode:=stats \
//        code/agent_a2_24_wsplit_contact_cover.m
//
//    magma -b Mode:=ff_disc Primes:="11,13,17" \
//        code/agent_a2_24_wsplit_contact_cover.m
//////////////////////////////////////////////////////////////////////

SetColumns(0);

if not assigned MemGB then
    MemGB := 4;
elif Type(MemGB) eq MonStgElt then
    MemGB := StringToInteger(MemGB);
end if;
SetMemoryLimit(MemGB*10^9);

if not assigned Mode then
    Mode := "ff_disc";
elif Type(Mode) ne MonStgElt then
    Mode := Sprint(Mode);
end if;

if not assigned Primes then
    Primes := "11,13,17";
elif Type(Primes) ne MonStgElt then
    Primes := Sprint(Primes);
end if;
PrimeList := [StringToInteger(s) : s in Split(Primes, ",")];

Z := Integers();
Q := Rationals();

function ParseQ(x)
    if Type(x) eq MonStgElt then
        parts := Split(x, "/");
        if #parts eq 1 then
            return Q!StringToInteger(parts[1]);
        end if;
        return Q!StringToInteger(parts[1])/Q!StringToInteger(parts[2]);
    end if;
    return Q!x;
end function;

if not assigned SampleLimit then
    SampleLimit := 12;
elif Type(SampleLimit) eq MonStgElt then
    SampleLimit := StringToInteger(SampleLimit);
end if;

if not assigned TopN then
    TopN := 8;
elif Type(TopN) eq MonStgElt then
    TopN := StringToInteger(TopN);
end if;

if not assigned IncludeBeta0 then
    IncludeBeta0 := true;
elif Type(IncludeBeta0) eq MonStgElt then
    IncludeBeta0 := IncludeBeta0 in {"true", "True", "1", "yes", "Yes"};
end if;

if not assigned Delta then
    Delta := Q!2;
else
    Delta := ParseQ(Delta);
end if;

