if not assigned DoEliminateM then
    DoEliminateM := false;
elif Type(DoEliminateM) eq MonStgElt then
    DoEliminateM := DoEliminateM in {"true", "True", "1", "yes", "Yes"};
end if;

if not assigned SearchH then
    SearchH := 10;
elif Type(SearchH) eq MonStgElt then
    SearchH := StringToInteger(SearchH);
